/// Whether the name is a well-known built-in global identifier whose access is side-effect-free.
///
/// This includes standard built-in objects/functions (e.g. `Math`, `Object`, `JSON`) that are
/// always safe to access, as well as commonly used environment globals (e.g. `console`, `window`)
/// which are only recognized when they are known to be global references.
#[rustfmt::skip]
fn is_known_global_identifier(name: &str) -> bool {
    matches!(name,
        // Built-in objects and functions
        "Math" | "Array" | "Object" | "JSON" | "Reflect" | "Symbol" | "Promise"
        | "Map" | "Set" | "WeakMap" | "WeakSet"
        | "parseInt" | "parseFloat" | "isNaN" | "isFinite"
        | "encodeURI" | "decodeURI" | "globalThis"
        // Environment globals (browser / node)
        | "console" | "document" | "window" | "fetch"
    )
}

/// Whether reading `object.property` (where `object` is a known global) is side-effect-free.
///
/// e.g. `Math.PI`, `Object.keys`, `console.log`
#[rustfmt::skip]
fn is_known_global_property(object: &str, property: &str) -> bool {
    match object {
        "Math" => matches!(property, "PI" | "E" | "abs" | "floor" | "random"),
        "Object" => matches!(property, "keys" | "create" | "assign" | "prototype"),
        "Reflect" => matches!(property, "apply" | "get"),
        "Symbol" => matches!(property, "iterator" | "asyncIterator"),
        "JSON" => matches!(property, "parse" | "stringify"),
        "console" => matches!(property, "log" | "error" | "warn"),
        _ => false,
    }
}

